
window.enhancedTranslation = {
    init: function() {
        const initFn = () => {
            if (window.languageSwitcher) {
                this.extendTranslations();
                this.extendApplyLanguage();
                console.log("增强翻译功能已初始化");
            } else {
                console.error("语言切换器加载超时");
            }
        };

        if (window.languageSwitcher) {
            initFn();
        } else {
            const interval = setInterval(() => {
                if (window.languageSwitcher) {
                    clearInterval(interval);
                    initFn();
                }
            }, 200);
        }
    },

    extendTranslations: function() {
        window.languageSwitcher.translations = window.languageSwitcher.translations || {};
        window.languageSwitcher.translations.sections = {};
        
        // Fetch translations from site-config.json
        fetch('/data/site-config.json')
            .then(response => response.json())
            .then(config => {
                if (config.nav_translations) {
                    window.languageSwitcher.translations.sections.titles = config.nav_translations.sections;
                    window.languageSwitcher.translations.common = config.nav_translations.common;
                    
                    // If current language is English, re-apply translations to ensure new data takes effect
                    if (window.languageSwitcher.currentLanguage === 'en') {
                        this.translatePage('en');
                    }
                }
            })
            .catch(err => console.error("Failed to load navigation translations:", err));
            
        // Default empty structure to prevent errors before fetch completes
        window.languageSwitcher.translations.sections.titles = {};
        window.languageSwitcher.translations.common = {};
    },

    extendApplyLanguage: function() {
        const originalApply = window.languageSwitcher.applyLanguage;
        window.languageSwitcher.applyLanguage = (lang) => {
            originalApply.call(window.languageSwitcher, lang);
            this.translatePage(lang);
        };
        
        // Listen for content changes (Nav Core generation)
        let isTranslating = false;
        const observer = new MutationObserver(() => {
            if (isTranslating) return;
            
            if (window.languageSwitcher.currentLanguage) {
                isTranslating = true;
                observer.disconnect();
                this.translatePage(window.languageSwitcher.currentLanguage);
                observeContent();
                isTranslating = false;
            }
        });
        
        const observeContent = () => {
            const contentContainer = document.getElementById('content-sections');
            if (contentContainer) observer.observe(contentContainer, { childList: true, subtree: true });
            const sidebarContainer = document.getElementById('main-menu');
            if (sidebarContainer) observer.observe(sidebarContainer, { childList: true, subtree: true });
        };
        
        observeContent();
    },

    translatePage: function(lang) {
        if (!window.languageSwitcher.translations.sections || !window.languageSwitcher.translations.sections.titles) return;
        
        const translations = window.languageSwitcher.translations;
        
        // 1. Translate Section Titles (Sidebar & Content)
        document.querySelectorAll('.sidebar-menu .title, #content-sections h4').forEach(el => {
            // Get text without icons
            const text = el.textContent.trim();
            const key = Object.keys(translations.sections.titles).find(k => k === text || translations.sections.titles[k].zh === text);
            
            if (key && translations.sections.titles[key]) {
                // Preserve icon if exists
                const icon = el.querySelector('i');
                if (icon) {
                    el.childNodes.forEach(node => {
                        if (node.nodeType === 3 && node.textContent.trim()) {
                            node.textContent = ' ' + translations.sections.titles[key][lang];
                        }
                    });
                } else {
                    el.textContent = translations.sections.titles[key][lang];
                }
            }
        });

        // 2. Translate Common Terms in Descriptions
        if (lang === 'en') {
            document.querySelectorAll('.box2 p').forEach(el => {
                let html = el.innerHTML;
                Object.keys(translations.common).forEach(key => {
                    const regex = new RegExp(key, 'g');
                    html = html.replace(regex, translations.common[key][lang]);
                });
                el.innerHTML = html;
            });
            
            // Translate specific UI elements
            const updateTimeEl = document.getElementById('sitetime');
            if (updateTimeEl) {
                // This is dynamic, so we might need a better way, but for now replace common time suffixes
                let text = updateTimeEl.textContent;
                Object.keys(translations.common).forEach(key => {
                    if (key.includes('更新')) {
                         text = text.replace(key, translations.common[key][lang]);
                    }
                });
                updateTimeEl.textContent = text;
            }
        } else {
            // Restore logic would require storing original text, which is complex.
            // For simple toggle, reloading or re-rendering might be safer, 
            // but here we assume 'zh' is default and generated from data.
            // If user switches en -> zh, we might rely on nav-core regenerating content or just simple replacement back?
            // Since nav-core generates ZH content by default, switching back to ZH usually requires re-fetching data or simple reload.
            // For now, this simple replacement is one-way or relies on consistent mapping.
        }
    }
};

// Initialize
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => window.enhancedTranslation.init());
} else {
    window.enhancedTranslation.init();
}
